  const production=entry.production?`<h3>Active production</h3>${entry.production.active.length?entry.production.active.map(job=>`<p>${escapeHtml(productName(job.recipe))} · ${job.readyAt<=Date.now()?"Ready to collect":`${remaining(job.readyAt)}s remaining`}</p>`).join(""):`<p>No active batch. This line makes ${escapeHtml(productName(entry.production.recipe))}.</p>`}`:"";
