function phoneBadge(app){const state=core.state,notes=state.phone.notifications.filter(note=>!note.read&&note.app===app).length,counts={messages:state.phone.messages.filter(message=>message.unread).length,orders:state.phone.orders.filter(order=>order.status==="offered").length,workers:state.workerRequests.filter(request=>request.status==="waiting").length,applicants:Object.values(state.applicants).filter(item=>["applied","shortlisted","interview","trial","counteroffer"].includes(item.status)).length,deliveries:state.activeDeliveries.filter(item=>!item.paid&&item.readyAt<=Date.now()).length,research:state.researchJobs.filter(item=>!item.resolved&&item.readyAt<=Date.now()).length,construction:state.outside.constructionJobs.filter(item=>!item.collected&&item.readyAt<=Date.now()).length,production:state.production.filter(item=>!item.collected&&item.readyAt<=Date.now()).length};return notes+(counts[app]||0);}
