const renderSewerObjectLegacy=renderSewerObject;
renderSewerObject=function(key){const [type]=String(key||"").split(":");if(type!=="sewer-map")return renderSewerObjectLegacy(key);const allowed=core.canViewMazeMap(),zoom=core.state.sewer.maze.mapZoom||1;return{title:"Hand-Drawn Sewer Maze Map",icon:"🗺️",kicker:"ONLY VISIBLE AT THE MAZE ENTRANCE",body:`<div class="dialog-body">${allowed?`<div class="maze-map expanded" style="--map-zoom:${zoom}" role="img" aria-label="Hand-drawn maintenance map with red pressure, blue canal, yellow power, green root, black center, exits, valves, and laboratory"><span class="map-entry">📍 MAZE START</span><span class="map-red">🔴 PRESSURE</span><span class="map-blue">🔵 CANALS</span><span class="map-yellow">🟡 POWER</span><span class="map-green">🟢 ROOTS</span><span class="map-center">⚫ ? CENTER</span><span class="map-lab">🧪 TEST LAB</span><span class="map-gate">🛞 VALVES</span><span class="map-exit">🪜 EXITS</span><span class="map-mystery">🍇 ?</span></div><div class="tag-row"><span class="tag">Red: pressure tunnels</span><span class="tag">Blue: flooded canals</span><span class="tag">Yellow: maintenance power</span><span class="tag">Green: root tunnels</span><span class="tag">Black: unknown center</span></div><p>Smudges hide exact routes, treasure, traps, and the true Mafia door. Walk beyond the Start Line and this complete view closes automatically.</p><div class="button-row"><button data-do="maze-map-zoom" data-value="out">Zoom out</button><button data-do="maze-map-zoom" data-value="in">Zoom in</button><button class="primary-button" data-do="study-maze-map">Study landmarks</button></div>`:`<section class="notice danger"><strong>Map unavailable.</strong> Return physically to the Maze Entrance. Neither the phone nor Sewer Journal can reveal the complete layout after the Start Line.</section>`}</div>`};};

function renderTree(treeId){const tree=core.state.trees.find(item=>item.id===treeId);if(!tree)return renderFruitBook();const fruit=Config.FRUIT_BY_ID[tree.fruit]||Config.FRUIT_BY_ID.apple,ripe=["ripe","golden"].includes(tree.status);return{title:`${fruit.name} Tree`,icon:tree.golden?"🌟":"🌳",className:"narrow",body:`<div class="dialog-body">${statStrip([["State",tree.status.replace("-"," ")],["Fruit",fruit.name],["Harvests",tree.harvests||0],["Watered",tree.watered?"Yes":"No"],["Fertilized",tree.fertilized?"Yes":"No"]])}<div class="game-card"><span class="big-icon">${fruit.icon}</span><h3>${ripe?"Ready to harvest":tree.diseased?"Treatment needed":`${remaining(tree.readyAt)}s until ripe`}</h3><p>Manual care improves yield and quality. Manual harvesting can award Research Points, XP, Fruit Coins, event fruit, and special quality.</p><button data-do="harvest-tree" data-id="${tree.id}" ${ripe?"":"disabled"}>${ripe?"Pick fruit":"Not ripe yet"}</button><div class="button-row" style="margin-top:8px"><button data-do="tree-care" data-id="${tree.id}" data-value="water">Water</button><button data-do="tree-care" data-id="${tree.id}" data-value="fertilize">Fertilize · $2</button><button data-do="tree-care" data-id="${tree.id}" data-value="treat">Treat disease · $3</button></div></div></div>`};}

