function handleWorldInteraction(entity){if(entity.type==="purchase-pad")return openPage("purchase-pad",entity.id);if(entity.type==="orchard-section")return feedback(core.harvestOrchardSection(entity.id,true),"Orchard Estate");if(entity.type==="tree")return openPage("tree",entity.id);if(entity.type==="district")return openPage("district",entity.id);if(entity.type==="crate"){feedback(core.collectDistrictCrate(entity.id),"Hidden crate");return;}if(entity.type==="worker")return openPage("worker",entity.id);if(entity.type==="applicant")return openPage("applicant",entity.id);if(entity.type==="manhole")return openPage("manhole",entity.id);if(entity.type==="outside-region")return openPage("outside-region",entity.id);if(entity.type==="outside-plot")return openPage("outside-plot",entity.id);if(entity.type==="outside-npc")return openPage("outside-npc",entity.id);if(entity.type==="outside-secret")return feedback(core.discoverSurfaceSecret(entity.id),"Outdoor secret");if(["train-station","cable-station"].includes(entity.type))return openPage("outside-transport");if(["sewer-exit","sewer-map","sewer-network-map","water-point","sewer-lab","sewer-valve","sewer-gate","sewer-shortcut","sewer-treasure","sewer-character","mafia-bouncer","mafia-symbol","plinko","fruit-slots","future-mafia-game","sewer-pump","maintenance-wing","red-puzzle","blue-puzzle","yellow-puzzle","green-puzzle","center-machine","forgotten-lab","sewer-garden","sewer-checkpoint"].includes(entity.type))return openPage("sewer-object",`${entity.type}:${entity.id}`);if(entity.type==="building"){const building=Config.BUILDING_BY_ID[entity.id],owned=core.state.buildings[entity.id];if(building.category==="Entertainment"){const cooldown=60000,last=owned.lastVisitAt||0;if(Date.now()-last<cooldown)return feedback(core.result(false,`${Math.ceil((cooldown-(Date.now()-last))/1000)} seconds until the next visitor group.`),building.name);owned.lastVisitAt=Date.now();const tickets=owned.level*2;core.state.tickets+=tickets;core.earnCash(owned.level*5,`${building.name} visitors`);core.addXp(owned.level*3);return feedback(core.result(true,`Visitors enjoyed ${building.name} and earned ${tickets} tickets.`),"Attraction visit");}toast(building.name,`${building.description} Level ${owned?.level||1}.`);}}

