document.addEventListener("click",event=>{const nav=event.target.closest("[data-nav]");if(nav){event.preventDefault();const page=nav.dataset.nav,sub=nav.dataset.page||nav.dataset.id||null;openPage(page,sub);return;}const action=event.target.closest("[data-action]");if(action){event.preventDefault();handleAction(action);return;}const operation=event.target.closest("[data-do]");if(operation){event.preventDefault();handleDo(operation);}});
document.addEventListener("pointerdown",event=>{const button=event.target.closest(".pad-buy.hold-required");if(!button)return;clearTimeout(padHoldTimer);button.classList.add("holding");padHoldTimer=setTimeout(()=>{button.dataset.held="true";button.dataset.processed="true";const pad=core.purchasePadById(button.dataset.id);if(pad)processPurchasePad(pad);button.classList.remove("holding");},700);});
document.addEventListener("pointerup",event=>{const button=event.target.closest(".pad-buy.hold-required");clearTimeout(padHoldTimer);padHoldTimer=null;if(button)button.classList.remove("holding");});
